SELECT r.item_id AS item_id, v.attribuattribute_valuete_name AS attribuattribute_valuete_name, r.custom_attribute_value AS custom_attribute_value FROM items_rel_attributes r LEFT JOIN items_attribute_values v ON r.attribute_value_id = v.attribute_value_id WHERE r.item_id IN
#{iid}
AND r.attribute_type = 'item_spec' ORDER BY r.item_id DESC, r.attribute_sort DESC
